Settings.Decl:
type Settings struct {
	// Moderated hides new messages until they are approved.
	Moderated bool `db:"moderated"`
	// Closed refuses new messages.
	Closed bool `db:"closed"`
	// Notify receives an e-mail for every new message when set.
	Notify string `db:"notify"`
}

Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/comments.ListView */}}
{{/* Starting point generated by WebThings: a guestbook with its form. */}}
<main id="content">
    <h1>{{.Title}}</h1>

    {{/* The form returns the visitor here, to the element with the id {{.Key}}. */}}
    <section id="{{.Key}}">
        {{if eq .Result "sent"}}<p>Thank you for your message.</p>{{end}}
        {{if eq .Result "pending"}}<p>Thank you. Your message is shown after approval.</p>{{end}}
        {{if eq .Result "invalid"}}<p>Please fill in your name and a message.</p>{{end}}
        {{if eq .Result "throttled"}}<p>You posted several messages already. Please try again later.</p>{{end}}
        {{if and (eq .Result "closed") (not .Closed)}}<p>New messages were closed when you posted. Please try again.</p>{{end}}

        {{if .Closed}}
            <p>New messages are closed.</p>
        {{else}}
            {{form_open .Form}}
                {{form_field .Form "subject" nil}}
                {{form_field .Form "name" nil}}
                {{form_field .Form "email" nil}}
                {{form_field .Form "body" nil}}

                <button type="submit">Send</button>
            {{form_close}}
        {{end}}
    </section>

    {{range .Comments}}
        <article id="comment-{{.ID}}">
            <p><strong>{{.Name}}</strong> · {{date .CreatedAt}}</p>
            {{.HTML}}

            {{range .Replies}}
                <blockquote>
                    <p><strong>{{if .Staff}}Reply from the site{{else}}{{.Name}}{{end}}</strong> · {{date .CreatedAt}}</p>
                    {{.HTML}}
                </blockquote>
            {{end}}
        </article>
    {{else}}
        <p>No messages yet.</p>
    {{end}}

    <nav>
        {{with .NewerURL}}<a href="{{.}}">Newer</a>{{end}}
        {{with .OlderURL}}<a href="{{.}}">Older</a>{{end}}
    </nav>
</main>

Components.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/comments.ThreadView */}}
{{/* The comments on a subject, then the form: {{commentThread "remarks" .ID}}. */}}
<section class="wt-comments" id="{{.Key}}-comments" aria-labelledby="{{.Key}}-comments-title">
    <h2 class="wt-comments__title" id="{{.Key}}-comments-title">
        {{if .Count}}{{tl localizer "Comments (%d)" .Count}}{{else}}{{tl localizer "Comments"}}{{end}}
    </h2>

    {{if .Comments}}
        <ol class="wt-comments__list">
            {{range .Comments}}
                <li class="wt-comment" id="comment-{{.ID}}">
                    <header class="wt-comment__header">
                        <strong class="wt-comment__name">{{.Name}}</strong>
                        <time class="wt-comment__date wt-meta" datetime="{{.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{date .CreatedAt}}</time>
                    </header>
                    <div class="wt-comment__body">{{.HTML}}</div>

                    {{with .Replies}}
                        <ol class="wt-comment__replies">
                            {{range .}}
                                <li class="wt-comment wt-comment--reply{{if .Staff}} wt-comment--staff{{end}}" id="comment-{{.ID}}">
                                    <header class="wt-comment__header">
                                        <strong class="wt-comment__name">{{.Name}}</strong>
                                        {{if .Staff}}<span class="wt-comment__badge">{{tl localizer "Team"}}</span>{{end}}
                                        <time class="wt-comment__date wt-meta" datetime="{{.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{date .CreatedAt}}</time>
                                    </header>
                                    <div class="wt-comment__body">{{.HTML}}</div>
                                </li>
                            {{end}}
                        </ol>
                    {{end}}
                </li>
            {{end}}
        </ol>
    {{else}}
        <p class="wt-comments__empty wt-meta">{{tl localizer "No comments yet."}}</p>
    {{end}}

    {{commentForm .Key .Subject}}
</section>

{{/* @dot github.com/donseba/go-webthings/modules/comments.FormView */}}
{{/* The comment form of a subject with the result of the last post: {{commentForm "remarks" .ID}}. */}}
<div class="wt-comment-form" id="{{.Key}}">
    {{if .Closed}}
        <p class="wt-meta">{{tl localizer "Comments are closed."}}</p>
    {{else}}
        {{with .Result}}
            <p class="wt-notice" role="status">
                {{if eq . "sent"}}{{tl localizer "Thank you for your comment."}}
                {{else if eq . "pending"}}{{tl localizer "Thank you. Your comment is shown after approval."}}
                {{else if eq . "throttled"}}{{tl localizer "You posted several comments already. Please try again later."}}
                {{else if eq . "closed"}}{{tl localizer "Comments were closed when you posted. Please try again."}}
                {{else if eq . "invalid"}}{{tl localizer "Please fill in your name and a comment."}}{{end}}
            </p>
        {{end}}

        {{/* The form returns the visitor to the element with the id {{.Key}}. */}}
        {{form_open .Form}}
            {{form_field .Form "subject" nil}}

            <h3 class="wt-form__title">{{tl localizer "Leave a comment"}}</h3>

            {{form_field .Form "name" nil}}
            {{form_field .Form "email" nil}}
            {{form_field .Form "body" nil}}

            {{if .Moderated}}<p class="wt-form__help">{{tl localizer "Comments are shown after approval."}}</p>{{end}}

            <button class="wt-button" type="submit">{{tl localizer "Post comment"}}</button>
        {{form_close}}
    {{end}}
</div>

Mail.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/comments.NotifyView */}}
{{/* Sent to the notification address of the settings, in the admin's language. */}}
{{define "subject"}}{{.Title}}: {{.Name}}{{end}}

{{define "text"}}
{{if .Pending}}{{tl localizer "A new message waits for approval."}}{{else}}{{tl localizer "A new message was posted."}}{{end}}

{{.Name}}{{with .Email}} <{{.}}>{{end}}

{{.Body}}
{{with .PageURL}}
{{tl localizer "Page:"}} {{.}}
{{- end}}
{{tl localizer "Review:"}} {{.ReviewURL}}
{{end}}

Types.Decl:
type Comment struct {
	ID      string
	Subject string
	Name    string
	// Body is the plain text as written.
	Body string
	// HTML is Body escaped, with paragraphs and line breaks.
	HTML template.HTML
	// Staff is set for replies written in the admin.
	Staff  bool
	Locale string
	// CreatedAt is in UTC; {{date .CreatedAt}} shows it in the site's timezone.
	CreatedAt time.Time
	// Replies are the approved replies, oldest first. Replies have none.
	Replies []Comment
}

type Entry struct {
	Subject string
	// ParentID makes the entry a reply. A reply to a reply is attached to the
	// top-level comment, so threads stay one level deep.
	ParentID string
	Name     string
	Email    string
	Body     string
	Locale   string
	// Path is the page the message was written on, for the admin.
	Path     string
	Approved bool
	Staff    bool
	// IPHash identifies the sender for a day; see Service.visitor.
	IPHash string
	// CreatedAt is when the message was written, for imports; zero is now.
	CreatedAt time.Time
}

type FormView struct {
	Key     string
	Subject string
	// Action is the address the form posts to.
	Action string
	// Form is the form's model (PostInput) for go-form's template
	// functions, such as {{form_open .Form}} and {{form_field .Form "name"
	// nil}}; it returns the visitor to the element with the id Key.
	Form form.RenderModel
	// Result is "sent", "pending", "invalid", "closed", "throttled" or "".
	Result string
	// Closed is set when the instance accepts no new comments.
	Closed bool
	// Moderated is set when new comments wait for approval.
	Moderated bool
}

type InboxGroup struct {
	Subject string
	// Title names the subject for people: the instance title for the
	// instance's own subject (a guestbook); otherwise the title of the
	// published content on the page the messages were written on, in the
	// admin's language when a message was written in it, or that page's
	// address when no published content is there; the subject key when no
	// message knows its page.
	Title string
	// Address is the page whose content Title names, shown with it.
	Address string
	Rows    []InboxRow
}

type InboxView struct {
	Title   string
	Pending int
	// Filters switch between pending, approved and all messages.
	Filters     admin.Tabs
	Groups      []InboxGroup
	SettingsURL string
	TrashURL    string
	Pager       admin.Pager
}

type ListView struct {
	// Title is the title of the page the module is placed on.
	Title string
	// Key is the instance key, for the template functions.
	Key string
	// Comments are the approved messages of every subject, newest first, with
	// their replies.
	Comments []Comment
	// Action is the address the form posts to.
	Action string
	// Subject is the value of the form's subject field.
	Subject string
	// Form is the form's model (PostInput) for go-form's template
	// functions, such as {{form_open .Form}} and {{form_field .Form "name"
	// nil}}; it returns the visitor to the element with the id Key.
	Form form.RenderModel
	// Result is the outcome of the visitor's last post: "sent", "pending",
	// "invalid", "closed", "throttled" or "".
	Result string
	// Closed is set when the instance accepts no new messages.
	Closed bool
	// Moderated is set when new messages wait for approval.
	Moderated bool
	// NewerURL and OlderURL page through the messages; empty at either end.
	NewerURL string
	OlderURL string
}

type NotifyView struct {
	Comment
	// Email is the visitor's address; empty when they gave none.
	Email string
	// Title is the instance's title, for example "Comments".
	Title string
	// Pending is set when the message waits for approval.
	Pending bool
	// PageURL is the page the message was written on; empty when unknown.
	PageURL string
	// ReviewURL opens the messages in the admin.
	ReviewURL string
}

type Service struct {
	// contains unexported fields
}

type Settings struct {
	// Moderated hides new messages until they are approved.
	Moderated bool `db:"moderated"`
	// Closed refuses new messages.
	Closed bool `db:"closed"`
	// Notify receives an e-mail for every new message when set.
	Notify string `db:"notify"`
}

type ThreadView struct {
	// Key is the instance key, for {{commentForm .Key .Subject}}.
	Key     string
	Subject string
	// Comments are oldest first, each with its approved Replies.
	Comments []Comment
	// Count is the number of approved comments and replies.
	Count int
}
